import sympy
import itertools

def search_solutions_improved(max_k, max_a):
    solutions = {1}
    for k in range(1, max_k + 1):
        # a_tuple is a sorted tuple of exponents to avoid permutations
        for a_tuple in itertools.combinations_with_replacement(range(1, max_a + 1), k):
            target = 1
            for a in a_tuple:
                target *= (12 * a + 1)

            factors = sympy.factorint(target)
            exponents = sorted(factors.values(), reverse=True)
            sorted_a = sorted(a_tuple, reverse=True)

            if exponents == sorted_a:
                # Check that the number of prime factors is exactly k
                if len(exponents) == k:
                    solutions.add(target)
    return solutions

print(search_solutions_improved(6, 15))
